import React, { useEffect, useState } from 'react';
import './App.css';

function App() {
  const [movies, setMovies] = useState([]);
  const [selectedMovie, setSelectedMovie] = useState(null);

  // Fetch movies from backend
 useEffect(() => {
  fetch('/api/movies')
    .then(res => res.json())
    .then(data => {
      console.log("Fetched movies:", data); // Debug log
      setMovies(data);
    })
    .catch(err => console.error("Error fetching movies:", err));
}, []);


  // Detail view
  if (selectedMovie) {
    return (
      <div className="movie-detail">
        <h2>{selectedMovie.title}</h2>
        <p><strong>Tagline:</strong> {selectedMovie.tagline}</p>
        <p><strong>Overview:</strong> {selectedMovie.overview}</p>
        <p><strong>Release Date:</strong> {new Date(selectedMovie.release_date).toLocaleDateString()}</p>
        <p><strong>Runtime:</strong> {selectedMovie.runtime} minutes</p>
        <p><strong>Vote Average:</strong> {selectedMovie.vote_average}/10</p>
        <button onClick={() => setSelectedMovie(null)}>Back to list</button>
      </div>
    );
  }

  // List view
  return (
    <div className="movie-list">
      {movies.map(m => (
        <div
          key={m.id}
          className="movie-card"
          onClick={() => setSelectedMovie(m)}
        >
          <h3>{m.title}</h3>
          <p>{m.tagline || "No tagline"}</p>
          <p>⭐ {m.vote_average}/10</p>
        </div>
      ))}
    </div>
  );
}

export default App;
